#include <stdio.h>
/*
 * ex04：系统调用的开销占比——为什么「少进几次内核」比「算得更快」更值钱
 * 一次系统调用的成本 ≈ 保存现场 + 切换栈 + 切换页表/PCID + 查表 + 恢复
 * 典型量级：普通函数调用 ~2ns，系统调用 ~500ns~1.5us（含 Spectre 缓解后更贵）。
 * 本程序对比「每条记录写一次」与「攒 64 条批量写一次」的总耗时。
 */
int main(void) {
    long records = 1000000;          /* 要写的记录数 */
    double syscall_ns = 1200.0;      /* 单次系统调用耗时(ns)，含进出内核 */
    double work_ns = 40.0;           /* 每条记录的用户态处理耗时(ns) */

    long sc_naive = records;                    /* 朴素：每条一次 write */
    long sc_batch = records / 64;               /* 批量：攒 64 条一次 write */

    double t_naive = (sc_naive * syscall_ns + records * work_ns) / 1e6;  /* ms */
    double t_batch = (sc_batch * syscall_ns + records * work_ns) / 1e6;

    printf("记录数=%ld  单次系统调用=%.0fns  单条处理=%.0fns\n", records, syscall_ns, work_ns);
    printf("------------------------------------------------------------\n");
    printf("%-14s %12s %14s %12s\n", "策略", "系统调用次数", "总耗时(ms)", "占比");
    printf("%-14s %12ld %14.1f %11.1f%%\n", "逐条 write", sc_naive, t_naive,
           100.0 * sc_naive * syscall_ns / 1e6 / t_naive);
    printf("%-14s %12ld %14.1f %11.1f%%\n", "64 条批量写", sc_batch, t_batch,
           100.0 * sc_batch * syscall_ns / 1e6 / t_batch);
    printf("\n加速比 = %.2fx\n", t_naive / t_batch);
    printf("结论：用户态计算只占 %.1f%%，剩下全是「过边界的过路费」。\n",
           100.0 * records * work_ns / 1e6 / t_naive);
    printf("工程对应：stdio 缓冲区、bufio、io_uring、批量提交，本质都是同一件事。\n");
    return 0;
}
